    "bare_hardware": {
      "achieved": true,
      "observations": "Hardware like the locker handle and chair joints appear as distinct, unpainted metal elements in the as-built views."
    },
    "dark_trim": {
      "achieved": true,
      "observations": "Subtle dark trim is visible on the locker's base and edges in the as-built state, providing a grounded look."
    },
    "edge_corrosion": {
      "achieved": true,
      "observations": "The aged states show significant rust and paint loss concentrated on the corners and edges of both the chair and the locker."
    },
    "rust_runs": {
      "achieved": true,
      "observations": "Narrow, vertical rust streaks are clearly visible on the vertical faces of the aged locker and the chair's backrest."
    },
